import React, { useEffect, useState } from 'react'
import { fetchPokemons } from '../data/pokemonData' // Import fetchPokemons function

function RandomPokemonImage() {
  const [imageUrl, setImageUrl] = useState('')
  const [loading, setLoading] = useState(true) // To track loading state

  useEffect(() => {
    const getImageUrl = async () => {
      try {
        const pokemons = await fetchPokemons()

        if (pokemons && pokemons.length > 0) {
          const randomIndex = Math.floor(Math.random() * pokemons.length)
          const randomPokemon = pokemons[randomIndex] // Get a random Pokémon

          // Prefix the relative image URL with the backend base URL (http://localhost:3000)
          const fullImageUrl = `http://localhost:3000${firstPokemon.imageUrl.replace(
            '../',
            '/'
          )}`

          setImageUrl(fullImageUrl) // Set the absolute image URL
        }
      } catch (error) {
        console.error('Error fetching Pokémon:', error)
      } finally {
        setLoading(false) // Set loading to false after the fetch is complete
      }
    }

    getImageUrl() // Fetch the Pokémon image URL on component mount
  }, [])

  return (
    <div className='p-8'>
      {loading ? (
        <p>Loading Pokémon...</p>
      ) : imageUrl ? (
        <img
          src={imageUrl}
          alt='First Pokémon'
          style={{ width: '100px', height: '100px', objectFit: 'cover' }}
        />
      ) : (
        <p>No Pokémon data available</p>
      )}
    </div>
  )
}

export default RandomPokemonImage
